# Surah Fatir (chapter 35) — part 2: ayat 11-20 (IDs 3671-3680)
SURAH = 35

ENTRIES = {
3671: (
"اور اللہ نے تمہیں مٹی سے پیدا کیا پھر نطفہ سے پھر تمہیں جوڑے بنایا — کوئی مادہ نہ حاملہ ہوتی ہے اور نہ جنتی مگر اس کے علم سے — اور کوئی عمر دراز والا عمر دراز نہیں کیا جاتا اور نہ کسی کی عمر کم کی جاتی ہے مگر یہ کہ وہ کتاب میں ہے — بے شک یہ اللہ پر آسان ہے",
"""۱۔ تخلیقِ انسانی — مٹی؛ نطفہ؛ جوڑے؛ اللہ کا علم؛ کتابِ اجل؛ آسان۔
۲۔ ’’وَاللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَۃٍ ثُمَّ جَعَلَكُمْ أَزْوَاجًا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِ إِلَّا فِي كِتَابٍ إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ‘‘ — اور اللہ نے تمہیں مٹی سے پیدا کیا پھر نطفہ سے پھر تمہیں جوڑے بنایا — کوئی مادہ نہ حاملہ ہوتی ہے اور نہ جنتی مگر اس کے علم سے — اور کوئی عمر دراز والا عمر دراز نہیں کیا جاتا اور نہ کسی کی عمر کم کی جاتی ہے مگر یہ کہ وہ کتاب میں ہے — بے شک یہ اللہ پر آسان ہے — یعنی اور اللہ نے تمہیں مٹی سے پیدا کیا پھر نطفہ سے پھر تمہیں جوڑے بنایا کوئی مادہ نہ حاملہ ہوتی ہے اور نہ جنتی مگر اس کے علم سے اور کوئی عمر دراز والا عمر دراز نہیں کیا جاتا اور نہ کسی کی عمر کم کی جاتی ہے مگر یہ کہ وہ کتاب میں ہے بے شک یہ اللہ پر آسان ہے۔
۳۔ عملی سبق: تخلیقِ انسانی میں قدرتِ الٰہی دیکھو؛ تقدیر پر بھروسہ رکھو؛ اللہ سے ڈرو۔"""
),
3672: (
"اور کوئی دو سمندر برابر نہیں — یہ میٹھا ہے میٹھا ہے خوشگوار — اور یہ کھارا ہے تلخ — اور تم دونوں میں سے تازہ گوشت کھاتے ہو اور زیور نکالتے ہو جسہیں تم پہنتے ہو — اور تم دیکھتے ہو کشتیوں کو اس میں چلتی ہوئی تاکہ تم اس کے فضل سے طلب کرو — اور تاکہ تم شکر ادا کرو",
"""۱۔ دو سمندر — میٹھا و کھارا؛ تازہ گوشت؛ زیور؛ کشتیاں؛ فضلِ الٰہی؛ شکر۔
۲۔ ’’وَمَا يَسْتَوِي الْبَحْرَانِ هَٰذَا عَذْبٌ فُرَاتٌ سَائِغٌ شَرَابُهُ وَهَٰذَا مِلْحٌ أُجَاجٌ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَۃً تَلْبَسُونَهَا وَتَرَى الْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا مِن فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ‘‘ — اور کوئی دو سمندر برابر نہیں — یہ میٹھا ہے میٹھا ہے خوشگوار — اور یہ کھارا ہے تلخ — اور تم دونوں میں سے تازہ گوشت کھاتے ہو اور زیور نکالتے ہو جسہیں تم پہنتے ہو — اور تم دیکھتے ہو کشتیوں کو اس میں چلتی ہوئی تاکہ تم اس کے فضل سے طلب کرو — اور تاکہ تم شکر ادا کرو — یعنی اور کوئی دو سمندر برابر نہیں یہ میٹھا ہے میٹھا ہے خوشگوار اور یہ کھارا ہے تلخ اور تم دونوں میں سے تازہ گوشت کھاتے ہو اور زیور نکالتے ہو جسہیں تم پہنتے ہو اور تم دیکھتے ہو کشتیوں کو اس میں چلتی ہوئی تاکہ تم اس کے فضل سے طلب کرو اور تاکہ تم شکر ادا کرو۔
۳۔ عملی سبق: اللہ کی نعمتوں میں غور کرو؛ تجارت میں رزق مانگو؛ شکر کرو۔"""
),
3673: (
"وہ رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے — اور اس نے سورج اور چاند کو مسخر کیا ہے — ہر ایک ایک مقررہ وقت تک چلتا ہے — یہی اللہ ہے تمہارا رب — اس کے لیے حکومت ہے — اور جنہیں تم اس کے سوا پکارتے ہو وہ دھاگے کے تنے برابر بھی نہیں مالک",
"""۱۔ رات و دن — سورج و چاند کی مسخرگی؛ حکومت؛ مشرکین کے معبود بے اختیار۔
۲۔ ’’يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى ذَٰلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِن دُونِهِ مَا يَمْلِكُونَ مِن قِطْمِيرٍ‘‘ — وہ رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے — اور اس نے سورج اور چاند کو مسخر کیا ہے — ہر ایک ایک مقررہ وقت تک چلتا ہے — یہی اللہ ہے تمہارا رب — اس کے لیے حکومت ہے — اور جنہیں تم اس کے سوا پکارتے ہو وہ دھاگے کے تنے برابر بھی نہیں مالک — یعنی وہ رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے اور اس نے سورج اور چاند کو مسخر کیا ہے ہر ایک ایک مقررہ وقت تک چلتا ہے یہی اللہ ہے تمہارا رب اس کے لیے حکومت ہے اور جنہیں تم اس کے سوا پکارتے ہو وہ دھاگے کے تنے برابر بھی نہیں مالک۔
۳۔ عملی سبق: اللہ کی حکومت پر بھروسہ رکھو؛ شرک چھوڑو؛ اللہ سے ڈرو۔"""
),
3674: (
"اگر تم انہیں پکارو تو وہ تمہاری دعا نہیں سنتے — اور اگر سنیں بھی تو تمہیں جواب نہیں دیتے — اور قیامت کے دن وہ تمہارے شرک کا انکار کریں گے — اور تمہیں کوئی اس طرح نہیں بتاتا جیسا کہ خبیر",
"""۱۔ مشرکین کے معبود — دعا نہیں سنتے؛ جواب نہیں دیتے؛ قیامت میں انکار؛ خبیر کا علم۔
۲۔ ’’إِن تَدْعُوهُمْ لَا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَۃِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ‘‘ — اگر تم انہیں پکارو تو وہ تمہاری دعا نہیں سنتے — اور اگر سنیں بھی تو تمہیں جواب نہیں دیتے — اور قیامت کے دن وہ تمہارے شرک کا انکار کریں گے — اور تمہیں کوئی اس طرح نہیں بتاتا جیسا کہ خبیر — یعنی اگر تم انہیں پکارو تو وہ تمہاری دعا نہیں سنتے اور اگر سنیں بھی تو تمہیں جواب نہیں دیتے اور قیامت کے دن وہ تمہارے شرک کا انکار کریں گے اور تمہیں کوئی اس طرح نہیں بتاتا جیسا کہ خبیر۔
۳۔ عملی سبق: صرف اللہ سے دعا کرو؛ شرک چھوڑو؛ اللہ سے ڈرو۔"""
),
3675: (
"اے لوگو تم اللہ کے محتاج ہو — اور اللہ ہی بے نیاز و تعریف کا مستحق ہے",
"""۱۔ انسان کی حاجت — اللہ کی غنا؛ حمید۔
۲۔ ’’يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ‘‘ — اے لوگو تم اللہ کے محتاج ہو — اور اللہ ہی بے نیاز و تعریف کا مستحق ہے — یعنی اے لوگو تم اللہ کے محتاج ہو اور اللہ ہی بے نیاز و تعریف کا مستحق ہے۔
۳۔ عملی سبق: اپنی محتاجی مانو؛ اللہ سے اس کی مدد مانگو؛ شکر کرو۔"""
),
3676: (
"اگر وہ چاہے تو تمہیں لے جائے اور نئی مخلوق لے آئے",
"""۱۔ اللہ کی قدرت — فنا و پیدائش۔
۲۔ ’’إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ‘‘ — اگر وہ چاہے تو تمہیں لے جائے اور نئی مخلوق لے آئے — یعنی اگر وہ چاہے تو تمہیں لے جائے اور نئی مخلوق لے آئے۔
۳۔ عملی سبق: اللہ کی قدرت پر بھروسہ رکھو؛ فرماں بردار بنو؛ اللہ سے ڈرو۔"""
),
3677: (
"اور یہ اللہ پر کوئی مشکل نہیں",
"""۱۔ اللہ کی قدرت — ہر کام آسان۔
۲۔ ’’وَمَا ذَٰلِكَ عَلَى اللَّهِ بِعَزِيزٍ‘‘ — اور یہ اللہ پر کوئی مشکل نہیں — یعنی اور یہ اللہ پر کوئی مشکل نہیں۔
۳۔ عملی سبق: اللہ کی مدد پر بھروسہ رکھو؛ ناامیدی چھوڑو؛ اللہ سے ڈرو۔"""
),
3678: (
"اور کوئی بوجھ اٹھانے والا کسی دوسرے کا بوجھ نہیں اٹھاتا — اور اگر کوئی بڑی ذمہ داری والا کسی کے بوجھ کی طرف بلائے تو اس میں سے کچھ بھی نہ اٹھایا جائے گا چاہے وہ قرابت دار ہی کیوں نہ ہو — تم بس انہیں ڈراتے ہو جو اپنے رب سے غیب میں ڈرتے اور نماز قائم کرتے ہیں — اور جو پاک ہوتا ہے وہ اپنے لیے ہی پاک ہوتا ہے — اور اللہ کی طرف لوٹ کر جانا ہے",
"""۱۔ بوجھ اٹھانے کا اصول — فردی ذمہ داری؛ خفیتہ خوف؛ نماز؛ تزکیۃ نفس؛ مصیر۔
۲۔ ’’وَلَا تَزِرُ وَازِرَۃٌ وِزْرَ أُخْرَىٰ وَإِن تَدْعُ مُثْقَلَۃٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَيْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰ إِنَّمَا تُنذِرُ الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ وَأَقَامُوا الصَّلَاۃَ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِ وَإِلَى اللَّهِ الْمَصِيرُ‘‘ — اور کوئی بوجھ اٹھانے والا کسی دوسرے کا بوجھ نہیں اٹھاتا — اور اگر کوئی بڑی ذمہ داری والا کسی کے بوجھ کی طرف بلائے تو اس میں سے کچھ بھی نہ اٹھایا جائے گا چاہے وہ قرابت دار ہی کیوں نہ ہو — تم بس انہیں ڈراتے ہو جو اپنے رب سے غیب میں ڈرتے اور نماز قائم کرتے ہیں — اور جو پاک ہوتا ہے وہ اپنے لیے ہی پاک ہوتا ہے — اور اللہ کی طرف لوٹ کر جانا ہے — یعنی اور کوئی بوجھ اٹھانے والا کسی دوسرے کا بوجھ نہیں اٹھاتا اور اگر کوئی بڑی ذمہ داری والا کسی کے بوجھ کی طرف بلائے تو اس میں سے کچھ بھی نہ اٹھایا جائے گا چاہے وہ قرابت دار ہی کیوں نہ ہو تم بس انہیں ڈراتے ہو جو اپنے رب سے غیب میں ڈرتے اور نماز قائم کرتے ہیں اور جو پاک ہوتا ہے وہ اپنے لیے ہی پاک ہوتا ہے اور اللہ کی طرف لوٹ کر جانا ہے۔
۳۔ عملی سبق: اپنی ذمہ داری قبول کرو؛ غیب میں اللہ سے ڈرو؛ نماز قائم کرو۔"""
),
3679: (
"اور اندھے اور دیکھنے والے برابر نہیں",
"""۱۔ عدمِ مساوات — اندھا و بینا۔
۲۔ ’’وَمَا يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ‘‘ — اور اندھے اور دیکھنے والے برابر نہیں — یعنی اور اندھے اور دیکھنے والے برابر نہیں۔
۳۔ عملی سبق: ہدایت اور گمراہی میں فرق پہچانو؛ حق کو دیکھو؛ اللہ سے ڈرو۔"""
),
3680: (
"اور نہ اندھیرے اور نہ روشنی",
"""۱۔ عدمِ مساوات — اندھیرے و روشنی۔
۲۔ ’’وَلَا الظُّلُمَاتُ وَلَا النُّورُ‘‘ — اور نہ اندھیرے اور نہ روشنی — یعنی اور نہ اندھیرے اور نہ روشنی۔
۳۔ عملی سبق: ایمان کا نور اپناؤ؛ کفر کے اندھیروں سے بچو؛ اللہ سے ڈرو۔"""
),
}
